<?php use App\Core\Authorization; ?>
<div class="page-heading"><div><p class="eyebrow">Protection</p><h1>Insurance monitoring</h1><p>Track coverage and claims for students, teachers, and non-teaching employees.</p></div><div class="hero-actions insurance-heading-actions"><?php if(Authorization::allows('insurance.manage')):?><a class="button" href="<?=e(url('/insurance/employees'))?>">Employees</a><a class="button primary" href="<?=e(url('/insurance/create'))?>">Add policy</a><?php endif;?></div></div>
<div class="grid four insurance-summary"><article class="stat-card"><span>Active policies</span><strong><?=(int)($summary['active_count']??0)?></strong><small>Current coverage</small></article><article class="stat-card"><span>Expiring in 30 days</span><strong><?=(int)($summary['expiring_count']??0)?></strong><small>Needs attention</small></article><article class="stat-card"><span>Expired policies</span><strong><?=(int)($summary['expired_count']??0)?></strong><small>Past coverage date</small></article><article class="stat-card"><span>Open claims</span><strong><?=(int)($summary['open_claims']??0)?></strong><small>Submitted or under review</small></article></div>
<form class="insurance-filter" method="get"><input name="q" value="<?=e($q)?>" placeholder="Holder, policy number, or provider"><select name="holder_type"><option value="">All holder types</option><?php foreach(['student','teacher','employee'] as $x):?><option value="<?=$x?>" <?=$type===$x?'selected':''?>><?=e(ucfirst($x))?></option><?php endforeach;?></select><select name="status"><option value="">All statuses</option><?php foreach(['pending','active','expired','cancelled'] as $x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=e(ucfirst($x))?></option><?php endforeach;?></select><button class="button">Filter</button></form>
<section class="card table-card"><table><thead><tr><th>Policy holder</th><th>Type</th><th>Provider and policy</th><th>Coverage</th><th>Premium</th><th>Status</th><th>Claims</th><th></th></tr></thead><tbody><?php foreach($policies as $p):?><tr><td><strong><?=e($p['holder_name'])?></strong><br><small><?=e($p['reference_no'])?></small></td><td><?=e(ucfirst($p['holder_type']))?></td><td><strong><?=e($p['provider'])?></strong><br><small><?=e($p['policy_no'].' · '.($p['plan_name']?:'Standard plan'))?></small></td><td><?=e($p['coverage_start'])?><br><small>to <?=e($p['coverage_end'])?></small><?php if($p['status']==='active'&&$p['coverage_end']<=date('Y-m-d',strtotime('+30 days'))):?><br><span class="expiry-label">Expiring soon</span><?php endif;?></td><td><?=is_null($p['premium_amount'])?'—':'PHP '.number_format((float)$p['premium_amount'],2)?></td><td><span class="badge"><?=e($p['status'])?></span></td><td><?=(int)$p['claim_count']?></td><td><a class="button small" href="<?=e(url('/insurance/'.$p['id']))?>">View</a></td></tr><?php endforeach;?><?php if(!$policies):?><tr><td colspan="8" class="empty">No insurance policies found.</td></tr><?php endif;?></tbody></table></section>
